/**
 * Onboarding is idempotent at the application level.
 * Device keys are generated by the browser, never by this module.
 * The backend is responsible for the database lock and Turnkey ownership check.
 */
export type WalletRecord = {
  organizationId: string;
  turnkeyUserId: string;
  walletId?: string;
  evmAddress?: string;
  bitcoinAddress?: string;
};

export type WalletLookup = {
  wallet: WalletRecord | null;
  canActivate: boolean;
};

export type WalletEnrollmentResult = {
  state: "existing" | "created";
  wallet: WalletRecord;
};

export type WalletEnrollmentDependencies = {
  lookup: () => Promise<WalletLookup>;
  prepareDevice: () => Promise<string>;
  provision: (publicKey: string) => Promise<void>;
};

/**
 * Never create another wallet for a Clerk user who already has one.
 * On a new device, existing accounts must use the signed recovery path.
 */
export async function enrollWalletIfMissing(
  dependencies: WalletEnrollmentDependencies,
): Promise<WalletEnrollmentResult> {
  const current = await dependencies.lookup();
  if (current.wallet) return { state: "existing", wallet: current.wallet };
  if (!current.canActivate) throw new Error("wallet_not_available");

  const publicKey = await dependencies.prepareDevice();
  if (!/^(?:02|03)[0-9a-f]{64}$/.test(publicKey)) throw new Error("wallet_device_invalid");

  await dependencies.provision(publicKey);
  // A successful HTTP response is not proof of a persisted wallet.
  const confirmed = await dependencies.lookup();
  if (!confirmed.wallet?.organizationId || !confirmed.wallet.walletId) {
    throw new Error("wallet_not_confirmed");
  }
  if (!confirmed.wallet.evmAddress || !confirmed.wallet.bitcoinAddress) {
    throw new Error("wallet_accounts_missing");
  }
  return { state: "created", wallet: confirmed.wallet };
}
